class Account:
    def __init__(self):
        self.balance = 0
    def debit(self, amount):
        if amount > self.balance:
            print('Insufficient funds')
        else:
            self.balance -= amount
    def credit(self, amount):
        self.balance += amount
    def get_balance(self):
        print('Balance:', self.balance)

acct = Account()
acct.credit(100)
acct.debit(30)
acct.get_balance()
acct.debit(80)
acct.get_balance()

